SELECT reference_date,ticker,instrument_id,listing_id,instrument_type FROM bmll_data_feed.market_data.reference_prod WHERE reference_date IN (DATE '2025-03-18',DATE '2025-03-19',DATE '2025-04-03',DATE '2025-04-04',DATE '2025-04-07',DATE '2025-04-08',DATE '2025-04-09') AND ticker IN ('AVIR','AWRE','DOW','HCSG','IDYA','INTT','KOSS','NDSN','OFIX','REKR','IWM','SPY') AND mic='@SIP' AND is_alive ORDER BY reference_date,ticker;
